#define MAX_PROCESSES 32
#define USER_STACK_TOP 0x00bff000u
static pcb_t processes[MAX_PROCESSES];static unsigned int process_count;
static void frame_for(pcb_t*p,uint32_t entry,uint32_t stack,uint8_t user){registers_t*f=user?(registers_t*)p->initial_frame:(registers_t*)(p->kernel_stack+4096u-sizeof(registers_t));for(uint32_t i=0;i<15;i++)((uint32_t*)f)[i]=0;f->eip=entry;f->cs=user?0x1bu:0x08u;f->eflags=0x202u;f->useresp=stack;f->ss=user?0x23u:0x10u;p->interrupt_frame=0;}
static pcb_t*new_pcb(const char*name){unsigned int i;pcb_t*p;uint8_t grew=0;for(i=0;i<MAX_PROCESSES;i++)if(!processes[i].allocated)break;if(i==MAX_PROCESSES)return 0;if(i==process_count){process_count++;grew=1;}p=&processes[i];p->generation=(p->generation+1u)&0x00ffffffu;if(p->generation==0)p->generation=1;p->pid=(pid_t)((p->generation<<8)|(i+1u));p->allocated=1;p->state=PROCESS_READY;p->ticks=0;p->name=name;p->next=0;p->entry_point=0;p->user_stack=0;p->user_mode=0;p->address_space=vmm_create_address_space();if(!p->address_space){p->allocated=0;if(grew)process_count--;return 0;}p->parent_pid=0;p->exit_code=0;p->wait_for_pid=0;p->wait_status_ptr=0;p->wait_status=0;p->pending_signals=0;p->signal_mask=0;p->futex_key=0;p->futex_expected=0;p->started=0;p->interrupt_frame=0;return p;}
pcb_t*process_create_entry(const char*name,process_entry_fn entry){pcb_t*p=new_pcb(name);if(!p)return 0;p->entry_point=(uint32_t)entry;p->cpu_state.eip=(uint32_t)entry;p->cpu_state.eflags=0x202u;if(entry){uint32_t top=(uint32_t)&p->kernel_stack[4096]-64;*(uint32_t*)top=(uint32_t)entry;p->cpu_state.esp=top;frame_for(p,(uint32_t)entry,top,0);}return p;}
pcb_t*process_create_thread(const char*name,process_entry_fn entry){pcb_t*owner=scheduler_current();pcb_t*p;if(!owner||!owner->address_space||owner->user_mode||!entry)return 0;p=process_create_entry(name,entry);if(!p)return 0;if(p->address_space)vmm_destroy_address_space(p->address_space);p->address_space=owner->address_space;vmm_retain_address_space(p->address_space);p->parent_pid=owner->pid;return p;} pcb_t*process_create(const char*name){return process_create_entry(name,0);}
pcb_t*process_create_user(const char*name,uint32_t entry){pcb_t*p=new_pcb(name);if(!p||!p->address_space)return 0;uint32_t page=pmm_alloc_page();if(!page)return 0;if(vmm_map_user(p->address_space,USER_STACK_TOP-PAGE_SIZE,page,PAGE_WRITE)!=0){pmm_free_page(page);return 0;}p->entry_point=entry;p->user_stack=USER_STACK_TOP;p->user_mode=1;p->cpu_state.eip=entry;p->cpu_state.esp=USER_STACK_TOP;p->cpu_state.eflags=0x202u;frame_for(p,entry,USER_STACK_TOP,1);return p;}
void process_enter_user(pcb_t*p){if(!p||!p->user_mode||!p->address_space)return;scheduler_set_current(p);vmm_switch_address_space(p->address_space);tss_set_kernel_stack((uint32_t)&p->kernel_stack[4096]);p->state=PROCESS_RUNNING;enter_user_mode(p->entry_point,p->user_stack);}
int process_exit_with_status(pid_t pid,int32_t status){unsigned int i,j;for(i=0;i<process_count;i++)if(processes[i].allocated&&processes[i].pid==pid){processes[i].state=PROCESS_ZOMBIE;processes[i].exit_code=status;vfs_release_process(pid);for(j=0;j<process_count;j++)if(processes[j].allocated&&processes[j].parent_pid==pid&&processes[j].state==PROCESS_ZOMBIE)processes[j].parent_pid=0;for(j=0;j<process_count;j++)if(processes[j].allocated&&processes[j].parent_pid==pid&&processes[j].state==PROCESS_BLOCKED&&processes[j].wait_for_pid==pid){processes[j].state=PROCESS_READY;processes[j].wait_for_pid=0;processes[j].wait_status=processes[i].exit_code;if(processes[j].wait_status_ptr)*(int32_t*)processes[j].wait_status_ptr=processes[i].exit_code;if(processes[j].interrupt_frame)processes[j].interrupt_frame->eax=pid;scheduler_add(&processes[j]);}return 0;}return -1;} int process_exit(pid_t pid){return process_exit_with_status(pid,0);}
int process_wait(pid_t child,int32_t*status){pcb_t*parent=scheduler_current();unsigned int i;if(!parent)return-1;for(i=0;i<process_count;i++)if(processes[i].allocated&&processes[i].pid==child&&processes[i].parent_pid==parent->pid){if(processes[i].state==PROCESS_ZOMBIE){if(status)*status=processes[i].exit_code;if(processes[i].address_space){vmm_destroy_address_space(processes[i].address_space);processes[i].address_space=0;}vfs_release_process(child);processes[i].parent_pid=0;processes[i].state=PROCESS_READY;processes[i].next=0;processes[i].interrupt_frame=0;processes[i].allocated=0;return(int)child;}parent->wait_for_pid=child;parent->wait_status_ptr=(uint32_t)status;parent->state=PROCESS_BLOCKED;return 0;}return -1;} int process_send_signal(pid_t pid,uint32_t signal){unsigned int i;if(signal==0||signal>31u)return-1;if(signal==9u){if(process_exit_with_status(pid,128+9)!=0)return-1;return 0;}for(i=0;i<process_count;i++)if(processes[i].allocated&&processes[i].pid==pid&&processes[i].state!=PROCESS_ZOMBIE){processes[i].pending_signals|=1u<<signal;if(processes[i].state==PROCESS_BLOCKED){processes[i].state=PROCESS_READY;processes[i].futex_key=0;scheduler_add(&processes[i]);}return 0;}return-1;} int process_futex_wait(uint32_t key,uint32_t expected){pcb_t*p=scheduler_current();volatile uint32_t*word=(volatile uint32_t*)key;if(!p||key==0||vmm_validate_user_ptr(p->address_space,key,sizeof(uint32_t),1)!=0||*word!=expected)return-11;if(*word!=expected)return-11;p->futex_key=key;p->futex_expected=expected;p->state=PROCESS_BLOCKED;return 0;} int process_futex_selftest(void){pcb_t*p=scheduler_current();address_space_t*old;uint32_t key=0x00408000u;uint32_t page;int mismatch,equal,ok;if(!p||!p->address_space)return-1;old=vmm_current_address_space();vmm_switch_address_space(p->address_space);if(vmm_get_user_physical(p->address_space,key))return-1;page=pmm_alloc_page();if(!page||vmm_map_user(p->address_space,key,page,PAGE_WRITE)!=0){if(page)pmm_free_page(page);if(old)vmm_switch_address_space(old);else vmm_switch_address_space(0);return-1;}*(volatile uint32_t*)key=0;mismatch=process_futex_wait(key,1);equal=process_futex_wait(key,0);ok=mismatch==-11&&equal==0&&p->state==PROCESS_BLOCKED&&p->futex_key==key&&p->futex_expected==0;p->state=PROCESS_RUNNING;p->futex_key=0;p->futex_expected=0;vmm_unmap_user(p->address_space,key);if(old)vmm_switch_address_space(old);else vmm_switch_address_space(0);return ok?0:-1;} int process_pid_selftest(void){pcb_t*p=scheduler_current();pcb_t*child;pid_t first,second;int waited;if(!p||!p->allocated)return-1;child=process_create_entry("pid-test",0);if(!child)return-1;child->parent_pid=p->pid;first=child->pid;if(process_exit_with_status(first,0)!=0)return-1;waited=process_wait(first,0);if(waited!=(int)first)return-1;child=process_create_entry("pid-test-reuse",0);if(!child)return-1;child->parent_pid=p->pid;second=child->pid;if(second==first)return-1;if(process_exit_with_status(second,0)!=0)return-1;waited=process_wait(second,0);if(waited!=(int)second)return-1;return 0;} int process_futex_wake(uint32_t key,uint32_t count){unsigned int i,woken=0;if(key==0)return-1;for(i=0;i<process_count&&(count==0||woken<count);i++)if(processes[i].state==PROCESS_BLOCKED&&processes[i].futex_key==key){processes[i].futex_key=0;processes[i].state=PROCESS_READY;if(processes[i].interrupt_frame)processes[i].interrupt_frame->eax=0;scheduler_add(&processes[i]);woken++;}return(int)woken;}
int process_exec_path(const char*path){pcb_t*q=scheduler_current();uint8_t*image;int fd;ssize_t n;uint32_t entry;address_space_t*space;address_space_t*old;if(!q||!path)return-1;fd=vfs_open(path,0);if(fd<0)return-2;image=(uint8_t*)kmalloc(256u*1024u);if(!image){vfs_close(fd);return-12;}n=vfs_read(fd,image,256u*1024u);vfs_close(fd);if(n<=0||n==(ssize_t)(256u*1024u)){kfree(image);return-8;}space=vmm_create_address_space();if(!space){kfree(image);return-12;}if(!vmm_user_alloc(space,USER_STACK_TOP-PAGE_SIZE,1,PAGE_WRITE)||elf32_load(image,(uint32_t)n,space,&entry)!=0){vmm_destroy_address_space(space);kfree(image);return-8;}old=q->address_space;q->address_space=space;q->entry_point=entry;q->user_stack=USER_STACK_TOP;q->user_mode=1;q->cpu_state.eip=entry;q->cpu_state.esp=USER_STACK_TOP;kfree(image);if(old)vmm_destroy_address_space(old);process_enter_user(q);return 0;}
pcb_t*process_create_from_path(const char*name,const char*path){pcb_t*p;uint8_t*image;int fd;ssize_t n;uint32_t entry;address_space_t*old;if(!name||!path)return 0;fd=vfs_open(path,0);if(fd<0)return 0;image=(uint8_t*)kmalloc(256u*1024u);if(!image){vfs_close(fd);return 0;}n=vfs_read(fd,image,256u*1024u);vfs_close(fd);if(n<=0||n==(ssize_t)(256u*1024u)){kfree(image);return 0;}p=process_create_user(name,0);if(!p){kfree(image);return 0;}old=p->address_space;p->address_space=vmm_create_address_space();if(!p->address_space){p->address_space=old;kfree(image);return 0;}if(!vmm_user_alloc(p->address_space,USER_STACK_TOP-PAGE_SIZE,1,PAGE_WRITE)||elf32_load(image,(uint32_t)n,p->address_space,&entry)!=0){vmm_destroy_address_space(p->address_space);p->address_space=old;kfree(image);return 0;}vmm_destroy_address_space(old);p->entry_point=entry;p->cpu_state.eip=entry;p->cpu_state.esp=USER_STACK_TOP;frame_for(p,entry,USER_STACK_TOP,1);kfree(image);return p;}
void process_dump(void){unsigned int i;serial_write("PID STATE NAME\n");for(i=0;i<process_count;i++)if(processes[i].allocated){const char*s=processes[i].state==PROCESS_RUNNING?"running":processes[i].state==PROCESS_READY?"ready":processes[i].state==PROCESS_BLOCKED?"blocked":"zombie";kprintf("%u %s %s\n",processes[i].pid,s,processes[i].name?processes[i].name:"?");}}
int process_fork(void){pcb_t*parent=scheduler_current();if(!parent)parent=process_count?&processes[0]:process_create("init");pcb_t*child=new_pcb("fork-child");if(!child||!parent)return -1;child->cpu_state=parent->cpu_state;child->cpu_state.eax=0;child->entry_point=parent->entry_point;child->user_mode=parent->user_mode;child->user_stack=parent->user_stack;child->parent_pid=parent->pid;vfs_inherit_process(parent->pid,child->pid);if(parent->address_space){address_space_t*clone=vmm_clone_address_space_cow(parent->address_space);if(!clone){process_exit(child->pid);return -1;}vmm_destroy_address_space(child->address_space);child->address_space=clone;}if(parent->user_mode)frame_for(child,child->entry_point,child->user_stack,1);else if(child->entry_point)frame_for(child,child->entry_point,child->cpu_state.esp,0);return(int)child->pid;}
struct registers*process_initial_frame(pcb_t*p){if(!p)return 0;return p->user_mode?(struct registers*)p->initial_frame:(struct registers*)(p->kernel_stack+4096u-sizeof(registers_t));}
